import numpy as np
import pandas as pd
import random

def task_func(rows=3, cols=2, min_val=0, max_val=100, seed=0):
    random.seed(seed)
    np.random.seed(seed)

    rows = max(0, rows)
    cols = max(0, cols)

    if rows == 0:
        return pd.DataFrame(columns=range(cols))

    matrix = [[random.randint(min_val, max_val) for _ in range(cols)] for _ in range(rows)]
    return pd.DataFrame(matrix)
